#!/usr/bin/env bash
# Snapshot the working copy before applying a new drop.
#
#   bash backup.sh                     # snapshot C:\dev\license-revoked
#   bash backup.sh /path/to/project    # ...or somewhere else
#
# Writes ../license-revoked-backup-YYYYmmdd-HHMMSS/ next to the project and
# keeps the ten most recent, deleting older ones. Build output is skipped -
# it is regenerated by `pebble build` and is the bulk of the size.
set -euo pipefail

PROJ="${1:-/mnt/c/dev/license-revoked}"
PROJ="${PROJ%/}"
[ -d "$PROJ" ] || { echo "backup: no project at $PROJ"; exit 1; }
[ -f "$PROJ/package.json" ] || { echo "backup: $PROJ does not look like the project (no package.json)"; exit 1; }

PARENT="$(dirname "$PROJ")"
NAME="$(basename "$PROJ")"
STAMP="$(date +%Y%m%d-%H%M%S)"
DEST="$PARENT/$NAME-backup-$STAMP"

# The version being saved, so a backup directory says what is in it.
VER="$(grep -o '"version"[^,]*' "$PROJ/package.json" | head -1 | cut -d'"' -f4 || echo unknown)"

echo "backing up $PROJ (version $VER)"
mkdir -p "$DEST"
if command -v rsync >/dev/null 2>&1; then
  rsync -a --exclude build/ --exclude .git/ "$PROJ/" "$DEST/"
else
  # cp -a then prune, for machines without rsync
  cp -a "$PROJ/." "$DEST/"
  rm -rf "$DEST/build" "$DEST/.git"
fi
echo "$VER" > "$DEST/.backup-version"
echo "  -> $DEST"

# Keep the ten most recent.
mapfile -t OLD < <(ls -1dt "$PARENT/$NAME"-backup-* 2>/dev/null | tail -n +11 || true)
for d in "${OLD[@]:-}"; do
  [ -n "$d" ] || continue
  echo "  pruning old backup $(basename "$d")"
  rm -rf "$d"
done

echo "done. to restore:  rm -rf \"$PROJ\" && cp -a \"$DEST\" \"$PROJ\""
